import os, re
from collections import defaultdict

ROOT = "/bench/repo"
MODULE = "github.com/usememos/memos"

# Data layer: store and all subpackages
def is_data_layer(pkg_path):
    return pkg_path == "store" or pkg_path.startswith("store/")

def is_test_file(path):
    return path.endswith("_test.go") or "/test/" in path.replace("\\", "/")

def get_pkg_path(filepath):
    """Return package path relative to module root, e.g. server/router/api/v1"""
    rel = os.path.relpath(os.path.dirname(filepath), ROOT)
    if rel == ".":
        return ""
    return rel.replace("\\", "/")

# Find all non-test Go files
go_files = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    # skip .git, web, node_modules
    parts = dirpath.replace("\\", "/").split("/")
    if ".git" in parts or "/web/" in dirpath.replace("\\", "/") or dirpath.endswith("/web"):
        continue
    for fn in filenames:
        if fn.endswith(".go"):
            go_files.append(os.path.join(dirpath, fn))

# Entity types: top-level structs in store/*.go (not subdirs), excluding obvious non-entities
NON_ENTITY_PATTERNS = {
    "Store", "Cache", "Config",
}
QUERY_MUTATION_PREFIXES = ("Find", "Update", "Delete", "Create")
RESULT_SUFFIXES = ("Result", "QueryResult", "Mutation")

entity_types = {}  # name -> decl file
store_root = os.path.join(ROOT, "store")
for fn in os.listdir(store_root):
    if not fn.endswith(".go") or fn.endswith("_test.go"):
        continue
    path = os.path.join(store_root, fn)
    content = open(path).read()
    for m in re.finditer(r'^type\s+(\w+)\s+struct\s*\{', content, re.MULTILINE):
        name = m.group(1)
        if name in NON_ENTITY_PATTERNS:
            continue
        if any(name.startswith(p) for p in QUERY_MUTATION_PREFIXES):
            continue
        if any(name.endswith(s) for s in RESULT_SUFFIXES):
            continue
        entity_types[name] = path.replace(ROOT + "/", "")

print("=== Persistent entity types in store/ ===")
for name, path in sorted(entity_types.items()):
    print(f"  {name:25s}  {path}")

# Also check proto/gen/store for entity messages
proto_store = os.path.join(ROOT, "proto/gen/store")
proto_entities = {}
if os.path.isdir(proto_store):
    for fn in os.listdir(proto_store):
        if fn.endswith(".pb.go"):
            path = os.path.join(proto_store, fn)
            content = open(path).read()
            for m in re.finditer(r'^type\s+(\w+)\s+struct\s*\{', content, re.MULTILINE):
                proto_entities[m.group(1)] = path.replace(ROOT + "/", "")

print("\n=== Proto gen/store types ===")
for name in sorted(proto_entities):
    print(f"  {name}")

# Count references per entity type
# Pattern: store.TypeName or just TypeName after store import
def count_refs(entity_name, include_tests=False):
    pkg_refs = defaultdict(set)  # pkg -> set of files
    patterns = [
        re.compile(r'\bstore\.' + re.escape(entity_name) + r'\b'),
        re.compile(r'\*store\.' + re.escape(entity_name) + r'\b'),
        re.compile(r'\[\]store\.' + re.escape(entity_name) + r'\b'),
        re.compile(r'storepb\.' + re.escape(entity_name) + r'\b'),  # proto alias
    ]
    # For proto entities, also match storepb
    store_import = re.compile(r'storepb\s+"github.com/usememos/memos/proto/gen/store"')
    store_pkg_import = re.compile(r'"github.com/usememos/memos/store"')

    for fpath in go_files:
        if not include_tests and is_test_file(fpath):
            continue
        pkg = get_pkg_path(fpath)
        if is_data_layer(pkg):
            continue
        try:
            content = open(fpath).read()
        except:
            continue

        matched = False
        for pat in patterns:
            if pat.search(content):
                matched = True
                break

        # Also check unqualified use when file imports store package
        if not matched and store_pkg_import.search(content):
            if re.search(r'\b' + re.escape(entity_name) + r'\b', content):
                # verify it's likely the store type (conservative: require store. prefix already checked)
                # check for local type alias or field of entity
                if re.search(r'\b' + re.escape(entity_name) + r'\s*\{', content):
                    matched = True
                elif re.search(r'\*?' + re.escape(entity_name) + r'\b', content):
                    # could be false positive; skip unqualified unless store. found
                    pass

        if matched:
            pkg_refs[pkg].add(fpath.replace(ROOT + "/", ""))

    return pkg_refs

print("\n=== Reference counts (excluding tests, excluding data layer) ===")
results = []
for entity in sorted(entity_types.keys()):
    refs = count_refs(entity, include_tests=False)
    results.append((len(refs), entity, entity_types[entity], refs))

results.sort(reverse=True)
for count, entity, decl, refs in results:
    pkgs = sorted(refs.keys())
    print(f"\n{entity}: {count} distinct packages")
    print(f"  declared: {decl}")
    for p in pkgs:
        files = sorted(refs[p])
        print(f"    {p}: {', '.join(files[:3])}{'...' if len(files)>3 else ''}")

print("\n=== TOP 2 ===")
for count, entity, decl, refs in results[:2]:
    print(f"#{results.index((count,entity,decl,refs))+1}: {entity} - {count} packages - {decl}")

# Also run with tests included for comparison
print("\n=== With tests included (top 5) ===")
results_with_tests = []
for entity in sorted(entity_types.keys()):
    refs = count_refs(entity, include_tests=True)
    results_with_tests.append((len(refs), entity, refs))
results_with_tests.sort(reverse=True)
for count, entity, refs in results_with_tests[:5]:
    print(f"  {entity}: {count}")

# Check if top 2 changes with tests
top2_no = [(r[1], r[0]) for r in results[:2]]
top2_yes = [(r[1], r[0]) for r in results_with_tests[:2]]
print(f"\nTop 2 unchanged with tests: {top2_no == top2_yes}")
PYEOF

